let appLang = 'fr';
function t(key){
  var d = I18N[appLang] || I18N.fr;
  if(d[key] !== undefined) return d[key];
  return (I18N.fr[key] !== undefined) ? I18N.fr[key] : key;
}
function tArr(key){
  var d = I18N[appLang] || I18N.fr;
  return (d[key] instanceof Array) ? d[key] : ((I18N.fr[key] instanceof Array) ? I18N.fr[key] : []);
}
function setLang(lang){
  if(!I18N[lang]) return;
  appLang=lang;
  safeLsSet('bdg16_lang',lang);
  var li=I18N[lang];
  if(li.months){for(var i=0;i<12;i++) MN[i]=li.months[i];}
  if(li.monthsShort){for(var i=0;i<12;i++) MNS[i]=li.monthsShort[i];}
  if(li.days7){for(var i=0;i<7;i++) JRS[i]=li.days7[i];}
  updateAllTexts();
  refresh();
}

function _updateStaticTexts(lang){
  // Modales
  var authTitle=document.getElementById('auth-title');
  if(authTitle) authTitle.textContent='🌸 '+t('createAccount');
  // Placeholder modale groupe
  var grpInp=document.getElementById('grp-name-inp');
  if(grpInp) grpInp.placeholder=t('groupNamePlaceholder');
  // Direction RTL arabe
  document.body.style.direction=(lang==='ar'?'rtl':'ltr');
  // Badge plan topbar
  var tbp=document.getElementById('tbplan');
  if(tbp){
    var pname=PLANS[plan]?PLANS[plan].name:'Starter';
    tbp.textContent=pname+' ▾';
  }
  // Boutons dans modales paiement
  var payBtn=document.getElementById('pay-confirm-btn');
  if(payBtn) payBtn.textContent='🔒 '+t('pay');
  // Onboarding boutons
  var ob0skip=document.getElementById('ob0-skip');
  if(ob0skip) ob0skip.textContent=t('skipIntro');
}
function initLang(){
  var saved=localStorage.getItem('bdg16_lang');
  if(saved&&I18N[saved]) appLang=saved;
  var li=I18N[appLang];
  if(li.months){for(var i=0;i<12;i++) MN[i]=li.months[i];}
  if(li.monthsShort){for(var i=0;i<12;i++) MNS[i]=li.monthsShort[i];}
  if(li.days7){for(var i=0;i<7;i++) JRS[i]=li.days7[i];}
  updateAllTexts();
}

