let groups=[],curG='g1',admins=[],hist={},stats={},profile={},favs=[],utpls=[];
let editId=null,editAdm=null,fMonth=0,fType='';
let searchInput='',searchFiltered=null; // Axe 2 : état séparé
let ppPhoto='',mode='perso',plan='free';
let calY=new Date().getFullYear(),calM=new Date().getMonth();
let actTpl='t1',obStep=0;
let isOnline=navigator.onLine;
let pushGranted=false;
let searchDebounceTimer=null; // Axe 2 : debounce 600ms strict

// ── HELPERS ──
const mems=()=>(groups.find(g=>g.id===curG)||{members:[]}).members||[];
const setMems=a=>{const g=groups.find(g=>g.id===curG);if(g)g.members=a;};
const allMems=function(){return groups.reduce(function(a,g){return a.concat(g.members||[]);}, []);};
const PL=()=>PLANS[plan]||PLANS.bloom;
const ambLv=function(r){var a=AMB.slice().reverse();for(var i=0;i<a.length;i++){if(r>=a[i].m)return a[i];}return null;};
function ageBday(d,m,y){if(!y)return null;const n=new Date(),b=new Date(n.getFullYear(),m-1,d),t=new Date(n.getFullYear(),n.getMonth(),n.getDate());return n.getFullYear()-y+(b>=t?0:1);}
function isToday(d,m){const n=new Date();return d===n.getDate()&&m===n.getMonth()+1;}
function wasYest(d,m){const n=new Date(),y=new Date(n);y.setDate(n.getDate()-1);return d===y.getDate()&&m===y.getMonth()+1;}
function daysTill(d,m){const n=new Date(),x=new Date(n.getFullYear(),m-1,d);if(x<=n)x.setFullYear(n.getFullYear()+1);return Math.round((x-n)/86400000);}
function easter(y){const a=y%19,b=Math.floor(y/100),c=y%100,d=Math.floor(b/4),e=b%4,f=Math.floor((b+8)/25),g=Math.floor((b-f+1)/3),h=(19*a+b-d-g+15)%30,i=Math.floor(c/4),k=c%4,l=(32+2*e+2*i-h-k)%7,mm=Math.floor((a+11*h+22*l)/451);return{m:Math.floor((h+l-7*mm+114)/31),d:((h+l-7*mm+114)%31)+1};}
function ramadan(y){return({2025:{m:3,d:1},2026:{m:2,d:18},2027:{m:2,d:8},2028:{m:1,d:28}})[y]||{m:3,d:1};}
function cny(y){return({2025:{m:1,d:29},2026:{m:2,d:17},2027:{m:2,d:6},2028:{m:1,d:26}})[y]||{m:2,d:1};}
const tIco=tp=>({birthday:'🎂',wedding:'💍',work:'💼',custom:'⭐',other:'✏️'})[tp]||'✏️';
const tLbl=tp=>({birthday:t('evtBirthday'),wedding:t('evtWedding'),work:t('evtWork'),custom:t('evtCustom')})[tp]||(tp&&tp!=='other'?tp:t('evtOther'));
const ini=n=>(n||'').trim().split(' ').filter(Boolean).map(w=>w[0]).slice(0,2).join('').toUpperCase()||'?';
const esc=s=>(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#x27;');

// Axe 7 : Contexte historique pour récurrence intelligente
function buildHistCtx(memberId,maxItems=3){
  const h=(hist[String(memberId)]||[]);
  if(!h.length)return '';
  const items=h.slice(-maxItems).map(x=>(x.text||'').substring(0,100));
  return `\nMESSAGES PRÉCÉDENTS (ANNÉES PRÉCÉDENTES — NE PAS RÉPÉTER CES TOURNURES, SOIS CRÉATIF ET DIFFÉRENT) :\n${items.join('\n')}`;
}

// ── STORAGE ──
const safeLsSet=(k,v)=>{try{localStorage.setItem(k,v);}catch(e){}};
const sg=async(k,v)=>{try{if(window.storage)await window.storage.set(k,JSON.stringify(v));else localStorage.setItem(k,JSON.stringify(v));}catch(e){}};
const gg=async(k,d)=>{try{if(window.storage){const r=await window.storage.get(k);if(r&&r.value)return JSON.parse(r.value);}else{const r=localStorage.getItem(k);if(r)return JSON.parse(r);}}catch(e){}return d;};
const saveG=()=>{sg('bdg16_groups',groups);if(currentUser)dbSaveGroups(currentUser.uid,groups);};
const saveA=()=>sg('bdg16_admins',admins);
const saveH=()=>sg('bdg16_hist',hist);
const saveSt=()=>{sg('bdg16_stats',stats);if(currentUser)dbSaveStats(currentUser.uid,stats);};
const savePr=()=>{buildCats();sg('bdg16_profile',profile);if(currentUser)dbSaveProfile(currentUser.uid,profile);};
const saveF=()=>sg('bdg16_favs',favs);
const saveTp=()=>sg('bdg16_tpls',utpls);
// buildCats définie plus bas

// ── AXE 3 : PUSH NOTIFICATIONS (Service Worker PWA) ──
async function requestPush(){
  if(!('Notification' in window)){return false;}
  if(Notification.permission==='granted'){pushGranted=true;return true;}
  if(Notification.permission==='denied'){return false;}
  const perm=await Notification.requestPermission();
  pushGranted=perm==='granted';
  if(pushGranted){
    stats.pushEnabled=true;saveSt();
    schedulePushForToday();
  }
  return pushGranted;
}
function schedulePushForToday(){
  if(!pushGranted)return;
  const m=mems(),todays=m.filter(p=>isToday(p.day,p.month));
  todays.forEach(p=>{
    const msg=`🌸 C'est l'anniversaire de ${p.name} aujourd'hui ! Ouvrez Bloomday pour générer un message.`;
    // Notification immédiate si la permission est accordée
    if(Notification.permission==='granted'){
      new Notification('Bloomday 🌸',{body:msg,icon:'data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 48"><circle cx="24" cy="24" r="24" fill="%23D4A843"/></svg>'});
    }
  });
}
function checkPushNeeded(){
  if(pushGranted||Notification.permission==='denied')return;
  if(!localStorage.getItem('bdg16_push_asked')){
    safeLsSet('bdg16_push_asked','1');
    // Afficher le prompt push dans l'UI (render home le fera)
  }
}

