window.addEventListener('online',()=>{isOnline=true;document.getElementById('offline-banner').classList.remove('show');});
window.addEventListener('offline',()=>{isOnline=false;document.getElementById('offline-banner').classList.add('show');});
if(!navigator.onLine)document.getElementById('offline-banner').classList.add('show');

